export interface IKeyValueStore {
    setItem(key: string, value: unknown): Promise<void>;
    getItem<T>(key: string): Promise<T | null>;
    deleteItem(key: string): Promise<void>;
}

export class MemoryKeyValueStore implements IKeyValueStore {
    private data: Map<string, unknown> = new Map();

    public constructor() {}

    public async setItem(key: string, value: unknown): Promise<void> {
        this.data.set(key, value);
    }

    public async getItem<T>(key: string): Promise<T | null> {
        const value = this.data.get(key);
        return value !== undefined ? (value as T) : null;
    }

    public async deleteItem(key: string): Promise<void> {
        this.data.delete(key);
    }
}

export class LocalStorageKeyValueStore implements IKeyValueStore {
    public constructor(private localStorage: Storage) {}

    public async setItem(key: string, value: unknown): Promise<void> {
        this.localStorage.setItem(key, JSON.stringify(value));
    }

    public async getItem<T>(key: string): Promise<T | null> {
        const value = this.localStorage.getItem(key);
        if (value === null) {
            return null;
        }
        try {
            return JSON.parse(value) as T;
        } catch {
            return null;
        }
    }

    public async deleteItem(key: string): Promise<void> {
        this.localStorage.removeItem(key);
    }
}
